// Hand-written. Not generated by Speakeasy.
//
// Four settings were taken off authlete_service before 3.0.0, because taking
// an attribute away afterwards is a major version.
//
// Three Authlete 3.0 accepts and disregards, so a practitioner could write one,
// watch the apply succeed, and never learn it did nothing. They are removed in
// the overlay with x-speakeasy-terraform-ignore.
//
// The fourth, server_url, is worse than redundant. Setting it passes
// operations.WithServerURL, so the request goes straight to that URL, the
// origin never matches the one idpRoutingTransport watches for, and the
// transport neither redirects it nor injects organizationId and apiServerId. A
// self-managed deployment then fails with an IdP error naming neither cause.
// It has no schema node, so it is removed by a script instead.
//
// Either mechanism can be lost silently: an overlay entry can be dropped by an
// edit, and the script's edit is undone by every regeneration. The provider
// builds and passes its other tests with any of the four back.
package provider

import "testing"

func TestRemovedServiceAttributesStayRemoved(t *testing.T) {
	attrs := resourceSchema(t, NewServiceResource()).Attributes

	for name, why := range map[string]string{
		"id_token_dropped_on_issue_without_openid": "Authlete 3.0 accepts this and disregards it.\n\n" +
			"Restore x-speakeasy-terraform-ignore on " +
			"$.components.schemas.service.properties.idTokenDroppedOnIssueWithoutOpenid " +
			"in .speakeasy/terraform_overlay.yaml and regenerate.",
		"developer_sns_credentials": "Authlete 2.x social login. Accepted and disregarded.\n\n" +
			"Restore x-speakeasy-terraform-ignore on " +
			"$.components.schemas.service.properties.developerSnsCredentials " +
			"in .speakeasy/terraform_overlay.yaml and regenerate.",
		"supported_developer_snses": "Authlete 2.x social login. Accepted and disregarded.\n\n" +
			"Restore x-speakeasy-terraform-ignore on " +
			"$.components.schemas.service.properties.supportedDeveloperSnses " +
			"in .speakeasy/terraform_overlay.yaml and regenerate.",
		"server_url": "Setting this sends service create and delete straight to that " +
			"URL, so idp_routing.go never recognises the origin and never injects " +
			"organizationId or apiServerId.\n\n" +
			"A regeneration has most likely restored it. Run:\n\n" +
			"  python3 scripts/patch-resource-server-url.py",
	} {
		if _, present := attrs[name]; present {
			t.Errorf("authlete_service has a `%s` attribute again.\n\n%s", name, why)
		}
	}
}
